6	const logger = createLogger('CognitiveEngine');
7	
8	export interface PersonalityArchetype {
9	    name: string;
10	    weight: number;
11	    description: string;
12	    influence: string;
13	}
14	
15	/**
16	 * Defines the expected structure for metadata of 'literary_wisdom' lessons.
17	 */
18	interface LiteraryWisdomMetadata {
19	    title?: string;
20	    author?: string;
21	    reflection?: string;
22	    [key: string]: unknown;
23	}
24	
25	/**
26	 * Defines the expected row structure returned by the SQL query in getPersonalityCore.
27	 */
28	interface PersonalityRow {
29	    author: string | null;
30	    weight: number;
31	}
