33	/**
34	 * CognitiveEngine
35	 *
36	 * Manages the activation of literary wisdom into POG2's personality and thoughts.
37	 * Bridges the gap between passive memory (VectorDB) and active metabolism (MetabolicEngine).
38	 */
39	export class CognitiveEngine {
40	    constructor(
41	        private readonly vectorDB: VectorDB,
42	        private readonly client: ModelClient
43	    ) { }
44	
45	    /**
46	     * Performs a health check on the CognitiveEngine's dependencies.
47	     * @returns A promise resolving to an object indicating online status and details.
48	     */
49	    public async healthCheck(): Promise<{ online: boolean; details: string }> {
50	        const vCheck = (this.vectorDB as any).healthCheck();
51	        const cCheck = await this.client.healthCheck();
52	        const isOnline = vCheck.online && cCheck.online;
53	        return {
54	            online: isOnline,
55	            details: `Cognitive: ${isOnline ? 'ONLINE' : 'DEGRADED'} (Vector: ${vCheck.details}, Client: ${cCheck.details})`
56	        };
57	    }
58	
59	    /**
60	     * getActiveWisdom - Retrieves wisdom fragments relevant to a specific task.
61	     * @param task The task for which to synthesize wisdom.
62	     * @param limit The maximum number of wisdom fragments to retrieve.
63	     * @returns A Result containing the synthesized wisdom string or an error.
64	     */
65	    public async getActiveWisdom(task: string, limit = 3): Promise<Result<string>> {
66	        logger.info({ task }, 'Synthesizing literary wisdom for task-specific cognition');
67	
68	        // 1. Generate embedding for the specific task
69	        const embedRes = await this.client.embed(task);
70	        if (!embedRes.ok) {
71	            return err(embedRes.error);
72	        }
73	
74	        // 2. Search VectorDB for relevant wisdom
75	        const projectId = (this.vectorDB as any).projectId || 'literary';
76	        const searchRes = await (this.vectorDB as any).searchSimilar(embedRes.value, limit, projectId);
77	        if (!searchRes.ok) {
78	            return err(searchRes.error);
79	        }
80	
81	        const lessons: Lesson[] = searchRes.value;
82	        if (lessons.length === 0) {
83	            return ok('No relevant wisdom fragments found in literary substrate.');
84	        }
85	
86	        // 3. Synthesize into a readable wisdom string
87	        const wisdomFragments = lessons.map((lesson: Lesson, i: number) => {
88	            const meta = (lesson.metadata || {}) as LiteraryWisdomMetadata;
89	            const source = meta.title
90	                ? `"${meta.title}"${meta.author ? ` by ${meta.author}` : ''}`
91	                : 'Unknown Source';
92	            return `[${i + 1}] ${source}: ${lesson.text}`;
93	        });
94	
95	        return ok(wisdomFragments.join('\n\n'));
96	    }
97	
98	    /**
99	     * getPersonalityCore - Derives the dominant personality archetypes from absorbed wisdom.
100	     * @returns A Result containing an array of PersonalityArchetype objects or an error.
101	     */
102	    public async getPersonalityCore(): Promise<Result<PersonalityArchetype[]>> {
103	        logger.info('Deriving personality archetypes from literary substrate');
104	
105	        try {
106	            const db = (this.vectorDB as any).db;
107	            if (!db) {
108	                return err(new Error('VectorDB has no db instance for personality query'));
109	            }
110	
111	            const rows: PersonalityRow[] = db.prepare(`
112	                SELECT metadata->>'$.author' as author, COUNT(*) as weight
113	                FROM lessons
114	                WHERE type = 'literary_wisdom'
115	                GROUP BY author
116	                ORDER BY weight DESC
117	                LIMIT 5
118	            `).all();
119	
120	            const archetypes: PersonalityArchetype[] = rows
121	                .filter((r: PersonalityRow) => r.author)
122	                .map((r: PersonalityRow) => ({
123	                    name: r.author!,
124	                    weight: r.weight,
125	                    description: `Dominant literary influence from ${r.author}`,
126	                    influence: `${r.weight} absorbed passages`
127	                }));
128	
129	            return ok(archetypes);
130	        } catch (e) {
131	            return err(e instanceof Error ? e : new Error(String(e)));
132	        }
133	    }
134	}
