55	    private loadWhitelist() {
56	        const whitelistPath = join(this.projectRoot, '.metabolic-whitelist.json');
57	        if (existsSync(whitelistPath)) {
58	            try {
59	                const data = JSON.parse(readFileSync(whitelistPath, 'utf8'));
60	                this.whitelist = {
61	                    exemptPaths: data.exemptPaths || [],
62	                    exemptPatterns: data.exemptPatterns || []
63	                };
64	                logger.info({ pathCount: this.whitelist.exemptPaths.length }, 'Metabolic whitelist loaded');
65	            } catch (e) {
66	                logger.warn('Failed to load metabolic whitelist');
67	            }
68	        }
69	    }
70	
71	    private isWhitelisted(file: string): boolean {
72	        const normalizedFile = file.replace(/\\/g, '/');
73	        if (this.whitelist.exemptPaths.some(p => normalizedFile.includes(p))) return true;
74	        if (this.whitelist.exemptPatterns.some(p => new RegExp(p).test(normalizedFile))) return true;
75	        return false;
76	    }
