146	    private generateRemediations(violations: SovereignViolation[]): string[] {
147	        return violations.map(v => {
148	            if (v.type === 'PLACEHOLDER_DETECTED') {
149	                return `SOVEREIGN LAW VIOLATION: ${v.file}:${v.line} contains ephemeral code. Implement or excise.`;
150	            }
151	            return `Review ${v.context} for pedagogical grounding.`;
152	        });
153	    }
