411	    /**
412	     * gatherSovereignContext - Reads local rule and manifest files to inform thinking.
413	     */
414	    private gatherSovereignContext(): string {
415	        const paths = [
416	            join(this.projectRoot, '.rules.md'),
417	            join(this.projectRoot, 'pog2.md'),
418	            join(this.projectRoot, 'manifest.md'),
419	            join(this.projectRoot, 'POG2_KNOWLEDGEBASE.md'),
420	            // Local fallback
421	            join(process.cwd(), '.rules.md'),
422	            join(process.cwd(), 'pog2.md')
423	        ];
424	
425	        let context = '';
426	        const seen = new Set<string>();
427	        for (const p of paths) {
428	            if (existsSync(p)) {
429	                try {
430	                    const content = readFileSync(p, 'utf8');
431	                    // Simple hash or name check to avoid redundant context if files were just moved
432	                    const name = p.split(/[\\/]/).pop();
433	                    if (name && seen.has(name)) continue;
434	                    if (name) seen.add(name);
435	
436	                    context += `\nFILE: ${p}\n---\n${content}\n---\n`;
437	                } catch (e) {
438	                    logger.warn({ path: p }, 'Failed to read context file');
439	                }
440	            }
441	        }
442	        return context || 'No Sovereign Context found.';
443	    }
