301	            };
302	            return typeof p.collision_matrix !== 'undefined' ? distilled : payload;
303	        }
304	
305	        if (source === 'apos_bridge') {
306	            const time = p.timestamp || Date.now();
307	            const state = p.state || 'UNKNOWN';
308	            const text = p.text || '';
309	            const cityContext = p.metadata?.loc ? ` at location ${JSON.stringify(p.metadata.loc)}` : '';
310	            return `[APOS ${state} @ ${time}${cityContext}] ${text}`;
311	        }
312	
313	        const distilled: Record<string, unknown> = {};
314	        const structuralKeys = ['id', 'name', 'type', 'coordinates', 'interfaces', 'models'];
315	        
316	        for (const key of structuralKeys) {
317	            if (key in p) {
