65	        const promises = tasks.map(task => this.executeSingleTask(task));
66	        const results = await Promise.all(promises);
67	
68	        const totalLatency = Date.now() - startTime;
69	
70	        // Log results
71	        for (const r of results) {
72	            if (r.result.ok) {
73	                logger.info({ taskId: r.id, model: r.model, latency: r.latency }, 'Limb completed');
74	            } else {
75	                logger.error({ taskId: r.id, model: r.model, error: r.result.error.message }, 'Limb failed');
76	            }
77	        }
78	
79	        // Combine results using coordinator prompt if provided
80	        if (coordinatorPrompt && tasks.length > 1) {
81	            return this.coordinateResults(results, coordinatorPrompt, totalLatency);
82	        }
83	
84	        // Return individual results combined
85	        const combined = this.formatCombinedResults(results, totalLatency);
86	        return { ok: true, value: combined };
87	    }
