111	    /**
112	     * Coordinate multiple results through a synthesis model
113	     */
114	    private async coordinateResults(
115	        results: TaskResult[],
116	        coordinatorPrompt: string,
117	        totalLatency: number
118	    ): Promise<Result<EngineOutput>> {
119	        // Build combined context
120	        const combined = results.map(r => {
121	            const output = r.result.ok ? r.result.value.output : `ERROR: ${r.result.error.message}`;
122	            return `[${r.id} via ${r.model}]:\n${output}`;
123	        }).join('\n\n---\n\n');
124	
125	        const synthesisPrompt = `${coordinatorPrompt}\n\nINPUTS:\n${combined}\n\nSYNTHESIZE:`;
126	
127	        // Use the fast coding model for synthesis
128	        const synthesis = await this.client.call({
129	            model: this.config.codingFastModel,
130	            prompt: synthesisPrompt,
131	            temperature: 0.3
132	        });
133	
134	        if (!synthesis.ok) {
135	            return synthesis as Result<EngineOutput>;
136	        }
137	
138	        return {
139	            ok: true,
140	            value: {
141	                output: synthesis.value.response,
142	                data: {
143	                    parallelResults: results.map(r => ({
144	                        id: r.id,
145	                        model: r.model,
146	                        latency: r.latency,
147	                        success: r.result.ok
148	                    })),
149	                    totalLatency,
150	                    synthesisModel: this.config.codingFastModel
151	                }
152	            }
153	        };
154	    }
