184	    /**
185	     * Execute a coding task using the heavy + fast model approach
186	     * Heavy model plans, fast models implement in parallel
187	     */
188	    async executeCodingTask(task: string, context?: string): Promise<Result<EngineOutput>> {
189	        // Step 1: Planning (heavy model)
190	        this.renderer.info('Ã°Å¸Â§Â  Heavy model planning...');
191	        const planResult = await this.client.call({
192	            model: this.config.codingHeavyModel,
193	            prompt: `TASK: ${task}\n\n${context ? `CONTEXT:\n${context}\n\n` : ''}Create a detailed implementation plan. Break into up to 4 parallel subtasks.`,
194	            temperature: 0.2
195	        });
196	
197	        if (!planResult.ok) return planResult as Result<EngineOutput>;
198	
199	        const plan = planResult.value.response;
200	
201	        // Step 2: Extract subtasks (simplified - in reality use structured parsing)
202	        const subtasks = this.extractSubtasks(plan, task);
203	
204	        // Step 3: Execute subtasks in parallel
205	        this.renderer.info(`Ã°Å¸Â¦Â¾ Executing ${subtasks.length} subtasks in parallel...`);
