8	const logger = createLogger('ContextBuilder');
9	
10	/**
11	 * ContextBuilder - Smart multi-file context assembly.
12	 */
13	export class ContextBuilder {
14	    private readonly pinnedFiles: Set<string> = new Set();
15	
16	    constructor(
17	        private readonly vectorDB: VectorDB,
18	        private projectRoot: string,
19	        private readonly projectId: string,
20	        private readonly modelExecutor: ModelExecutor,
21	        private readonly rootStack: string[] = [],
22	        private readonly aiContextPath?: string
23	    ) {
24	        logger.debug({ vectorDB: !!this.vectorDB, executor: !!this.modelExecutor, roots: this.rootStack.length }, 'ContextBuilder initialized');
25	    }
26	
27	    pinFile(filePath: string): void {
28	        this.pinnedFiles.add(resolve(filePath));
29	    }
30	
31	    unpinFile(filePath: string): void {
32	        this.pinnedFiles.delete(resolve(filePath));
33	    }
34	
35	    async buildContext(filePath: string): Promise<FileContext & CodeContext> {
36	        if (!existsSync(filePath)) {
37	            return { path: filePath, content: '', primary: '', related: [], imports: [], sameDirectory: [] };
38	        }
39	
40	        const absPath = resolve(filePath);
41	        const content = readFileSync(absPath, 'utf8');
42	        const root = process.cwd();
43	
44	        // 1. Extract imports
45	        const imports = this.extractImports(content, absPath);
46	
47	        // 2. Same directory
48	        const sameDir = readdirSync(dirname(absPath))
49	            .filter(f => f.endsWith('.ts') || f.endsWith('.js'))
50	            .map(f => join(dirname(absPath), f))
51	            .filter(p => p !== absPath && !SovereignIgnoreManager.isIgnored(this.projectRoot, p))
52	            .slice(0, 10);
53	
54	        // 3. Semantically related Ã¢â‚¬â€ Currently restricted to pinned context.
55	        const related = Array.from(this.pinnedFiles).filter(p => p !== absPath);
56	
57	        return {
58	            path: absPath,
59	            content,
60	            primary: relative(root, absPath),
61	            related: related.map(p => relative(root, p)),
62	            imports: imports.map(p => relative(root, p)),
63	            sameDirectory: sameDir.map(p => relative(root, p))
64	        };
65	    }
66	
67	    private extractImports(content: string, filePath: string): string[] {
68	        const pattern = /import\s+.*from\s+['"](.+?)['"]/g;
69	        const imports: string[] = [];
70	        let match;
71	        while ((match = pattern.exec(content)) !== null) {
72	            const impPath = match[1];
73	            if (impPath?.startsWith('.')) {
74	                const resolved = this.resolvePath(impPath, filePath);
75	                if (resolved && !SovereignIgnoreManager.isIgnored(this.projectRoot, resolved)) {
76	                    imports.push(resolved);
77	                }
78	            }
79	        }
80	        return imports;
81	    }
82	
83	    async queryLessons(prompt: string, domainNamespace?: string): Promise<Lesson[]> {
84	        if (!this.modelExecutor || typeof this.modelExecutor.embed !== 'function') {
85	            return [];
86	        }
87	
88	        try {
89	            const embeddingResult = await this.modelExecutor.embed(prompt);
90	            if (isOk(embeddingResult) && this.vectorDB) {
91	                const arr = new Float32Array(embeddingResult.value);
92	                const similar = await this.vectorDB?.searchSimilar(arr, 20, this.projectId, domainNamespace);
93	                if (isOk(similar)) {
94	                    return similar.value;
95	                }
96	            }
97	        } catch (err) {
98	            logger.warn({ err }, 'Failed to query lessons from VectorDB');
99	        }
100	        return [];
101	    }
102	
103	    private resolvePath(imp: string, from: string): string | null {
104	        const exts = ['.ts', '.js', '/index.ts', '/index.js'];
105	        const base = resolve(dirname(from), imp);
106	        for (const ext of exts) {
107	            const p = base.endsWith(ext) ? base : base + ext;
108	            if (existsSync(p)) return p;
109	        }
110	        return null;
111	    }
112	
113	    formatForPrompt(context: FileContext & CodeContext): string {
114	        const parts: string[] = [];
115	        const append = (relPath: string, label: string) => {
116	            try {
117	                const abs = resolve(relPath);
118	                if (!existsSync(abs)) return;
119	                const content = readFileSync(abs, 'utf8');
120	                parts.push(`--- FILE: ${relPath} (${label}) ---`);
121	                parts.push('```typescript');
122	                parts.push(content);
123	                parts.push('```\n');
124	            } catch { /* ignore invalid paths */ }
125	        };
126	
127	        if (context.primary) append(context.primary, 'PRIMARY');
128	        context.imports?.forEach((i: string) => append(i, 'IMPORT'));
129	        context.sameDirectory?.forEach((s: string) => append(s, 'LOCAL'));
130	        context.related?.forEach((r: string) => append(r, 'PINNED'));
131	
132	        return parts.join('\n');
133	    }
134	
135	    async getGoldenTemplates(prompt: string): Promise<string[]> {
136	        // Retrieve established design patterns from the resources substrate
137	        const templatePath = resolve('resources/cloudflare-templates');
138	        if (!existsSync(templatePath)) return [];
139	        return readdirSync(templatePath).map(f => join(templatePath, f));
140	    }
141	
142	    getArchitectureAlignment(prompt: string, manifest: any): string[] {
143	        // Enforce alignment with the Sovereign Organism architectural rules
144	        return [manifest?.primaryGoal || 'SovereignDesign'];
145	    }
146	
147	    public healthCheck(): { online: boolean; details: string } {
148	        return { online: true, details: 'ContextBuilder multi-file substrate active.' };
149	    }
150	}
