759	    public verifyWork(manifest: PipelineManifest): Result<void> {
760	        const corrupt: string[] = [];
761	
762	        for (const artifact of manifest.scenes) {
763	            // Check Images
764	            for (const img of artifact.imagePaths) {
765	                if (!existsSync(img)) {
766	                    corrupt.push(`Scene ${artifact.index}: Project missing image substrate ${basename(img)}`);
767	                } else if (statSync(img).size < 100) { // Tiny file threshold
768	                    corrupt.push(`Scene ${artifact.index}: Corrupt/Empty image ${basename(img)}`);
769	                }
770	            }
771	
772	            // Check Voice
773	            if (artifact.voiceStatus === 'success' && artifact.voicePath) {
774	                if (!existsSync(artifact.voicePath)) {
775	                    corrupt.push(`Scene ${artifact.index}: Missing narration ${artifact.index}.wav`);
776	                } else if (statSync(artifact.voicePath).size < 1000) { // Narration is usually > 1KB
777	                    corrupt.push(`Scene ${artifact.index}: Narration too short/silent`);
778	                }
779	            }
780	        }
781	
782	        // Check for duplicates
783	        const seenIndices = new Set<number>();
784	        for (const scene of manifest.scenes) {
785	            if (seenIndices.has(scene.index)) {
786	                corrupt.push(`Duplicate scene index detected: ${scene.index}`);
787	            }
788	            seenIndices.add(scene.index);
789	        }
790	
791	        if (corrupt.length > 0) {
792	            return { ok: false, error: new Error(corrupt.join(' | ')) };
793	        }
794	
795	        return ok(undefined);
796	    }
