798	    private async withRetry<T>(fn: () => Promise<Result<T>>, maxRetries: number): Promise<Result<T>> {
799	        let lastError: Error | undefined;
800	        for (let attempt = 0; attempt <= maxRetries; attempt++) {
801	            const result = await fn();
802	            if (result.ok) return result;
803	            lastError = result.error;
804	            if (attempt < maxRetries) {
805	                const delayMs = Math.pow(2, attempt) * 1000;
806	                logger.warn({ attempt: attempt + 1, delayMs }, `Retry in ${delayMs}ms...`);
807	                await new Promise(resolve => setTimeout(resolve, delayMs));
808	            }
809	        }
810	        return { ok: false, error: lastError || new Error('Max retries exceeded') };
811	    }
