52	    private async connectToServer(name: string, config: MCPServerConfig): Promise<void> {
53	        logger.info({ server: name }, 'Ã°Å¸â€Å’ Engaging MCP Neural Link...');
54	
55	        try {
56	            const transport = new StdioClientTransport({
57	                command: config.command,
58	                args: config.args || [],
59	                env: { ...process.env, ...config.env } as Record<string, string>
60	            });
61	
62	            const client = new Client(
63	                { name: "POG2-cli", version: "1.1.2" },
64	                { 
65	                    capabilities: { tools: {} },
66	                    requestTimeout: 60000 
67	                } as any
68	            );
69	
70	            await client.connect(transport);
71	            this.clients.set(name, client);
72	
73	            logger.info({ server: name }, 'Successfully connected to MCP server');
74	
75	            const toolsRes = await client.listTools();
76	            const tools = toolsRes.tools || [];
77	
78	            // Add the hello callback trigger
79	            const helloCallback = (config as any).helloCallback;
80	            if (helloCallback) {
81	                logger.info({ server: name, callback: helloCallback }, 'Invoking MCP Handshake...');
82	                await client.callTool({ name: helloCallback, arguments: {} }).catch((e) => {
83	                     logger.warn({ server: name, callback: helloCallback, error: e.message }, 'Handshake triggered, ignoring lack of tool support.');
84	                });
85	            }
86	
87	            for (const t of tools) {
88	                this.registry.register({
89	                    name: `mcp_${name}_${t.name}`,
90	                    description: `[MCP:${name}] ${t.description}`,
91	                    domain: SovereignDomain.SYSTEM,
92	                    parameters: t.inputSchema as Record<string, unknown>,
93	                    execute: async (args): Promise<Result<EngineOutput>> => {
94	                        try {
95	                            const result = await client.callTool({
96	                                name: t.name,
97	                                arguments: args
98	                            }) as unknown as MCPToolResult;
99	
100	                            if (result.isError) {
101	                                const errorText = result.content.map((c: MCPContent) => c.text || JSON.stringify(c)).join('\n');
