135	    private async searchDuckDuckGo(query: string, count: number): Promise<SearchResult[]> {
136	        const encodedQuery = encodeURIComponent(query);
137	        const url = `https://html.duckduckgo.com/html/?q=${encodedQuery}`;
138	
139	        const response = await fetch(url, {
140	            headers: {
141	                'User-Agent': this.userAgent,
142	                'Accept': 'text/html',
143	                'Accept-Language': 'en-US,en;q=0.9'
144	            }
145	        });
146	
147	        if (!response.ok) {
148	            throw new Error(`Search failed: ${response.status} ${response.statusText}`);
149	        }
150	
151	        const html = await response.text();
152	        return this.parseDuckDuckGoResults(html, count);
