185	    private cleanHtml(html: string): string {
186	        return html
187	            .replace(/<[^>]+>/g, '')
188	            .replace(/&amp;/g, '&')
189	            .replace(/&lt;/g, '<')
190	            .replace(/&gt;/g, '>')
191	            .replace(/&quot;/g, '"')
192	            .replace(/&#39;/g, "'")
193	            .replace(/&nbsp;/g, ' ')
194	            .trim();
195	    }
