201	    private formatResults(results: SearchResult[], query: string): string {
202	        const lines = [`ðŸ” Web Search Results for "${query}":`, '='.repeat(50), ''];
203	        for (let i = 0; i < results.length; i++) {
204	            const r = results[i]!;
205	            lines.push(`${i + 1}. ${r.title}`);
206	            lines.push(`   URL: ${r.url}`);
207	            if (r.snippet) lines.push(`   ${r.snippet}`);
208	            lines.push('');
209	        }
210	        return lines.join('\n');
211	    }
