213	    async fetchUrl(url: string): Promise<Result<EngineOutput>> {
214	        try {
215	            const response = await fetch(url, { headers: { 'User-Agent': this.userAgent } });
216	            if (!response.ok) return { ok: false, error: new Error(`Failed to fetch ${url}: ${response.status}`) };
217	            const contentType = response.headers.get('content-type') || '';
218	            if (contentType.includes('application/json')) {
219	                const data = await response.json();
220	                return { ok: true, value: { output: JSON.stringify(data, null, 2), data: { url, contentType, body: data } } };
221	            }
