233	            .replace(/<style[^>]*>[\s\S]*?<\/style>/gi, '')
234	            .replace(/<nav[^>]*>[\s\S]*?<\/nav>/gi, '');
235	        const mainMatch = text.match(/<main[^>]*>([\s\S]*?)<\/main>/i) ||
236	            text.match(/<article[^>]*>([\s\S]*?)<\/article>/i);
