1	import type { Result, EngineOutput } from '../core/models.js';
2	import { Renderer } from '../ui/Renderer.js';
3	
4	export interface WebSearchParams {
5	    query: string;
6	    count?: number;
7	    deep?: boolean; // If true, fetches and summarizes top results
8	}
9	
10	export interface SearchResult {
11	    title: string;
12	    url: string;
13	    snippet: string;
14	}
15	
16	/**
17	 * WebSearchEngine Ã¢â‚¬â€ Free web search using DuckDuckGo HTML (no API key required)
18	 * Falls back to other free sources if needed.
19	 */
20	export class WebSearchEngine {
21	    private readonly userAgent = 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.0';
22	
23	    constructor(private readonly renderer: Renderer) { }
24	
25	    async search(params: WebSearchParams): Promise<Result<EngineOutput>> {
26	        const { query, count = 5 } = params;
27	
28	        try {
29	            // Use DuckDuckGo HTML version (no API key needed)
30	            const results = await this.searchDuckDuckGo(query, count);
31	
32	            if (results.length === 0) {
33	                return {
34	                    ok: true,
35	                    value: {
36	                        output: `No results found for "${query}".`,
37	                        data: { results: [], query }
38	                    }
39	                };
40	            }
41	
42	            if (params.deep) {
43	                this.renderer.info(`Initiating Deep Research Substrate for: ${query}`);
44	                const topResults = results.slice(0, 3);
45	                const scrapes = await Promise.all(topResults.map(r => this.fetchUrl(r.url)));
46	
47	                const combined = scrapes
48	                    .filter(s => s.ok)
49	                    .map((s, i) => `[SOURCE: ${topResults[i]!.title}]\n${(s as any).value.output}`)
50	                    .join('\n\n---\n\n');
51	
52	                return {
53	                    ok: true,
54	                    value: {
55	                        output: `[DEEP RESEARCH SUMMARY]\n${combined.slice(0, 15000)}`,
56	                        data: { results, query, deep: true }
57	                    }
58	                };
59	            }
60	
61	            const formatted = this.formatResults(results, query);
62	            return {
63	                ok: true,
64	                value: {
65	                    output: formatted,
66	                    data: { results, query, count: results.length }
67	                }
68	            };
69	        } catch (error) {
70	            return {
71	                ok: false,
72	                error: error instanceof Error ? error : new Error(String(error))
73	            };
74	        }
75	    }
76	
77	    private async searchDuckDuckGo(query: string, count: number): Promise<SearchResult[]> {
78	        const encodedQuery = encodeURIComponent(query);
79	        const url = `https://html.duckduckgo.com/html/?q=${encodedQuery}`;
80	
81	        const response = await fetch(url, {
82	            headers: {
83	                'User-Agent': this.userAgent,
84	                'Accept': 'text/html',
85	                'Accept-Language': 'en-US,en;q=0.9'
86	            }
87	        });
88	
89	        if (!response.ok) {
90	            throw new Error(`Search failed: ${response.status} ${response.statusText}`);
91	        }
92	
93	        const html = await response.text();
94	        return this.parseDuckDuckGoResults(html, count);
95	    }
96	
97	    private parseDuckDuckGoResults(html: string, count: number): SearchResult[] {
98	        const results: SearchResult[] = [];
99	
100	        // DuckDuckGo HTML structure parsing
101	        const resultRegex = /<div class="result[^"]*"[^>]*>[\s\S]*?<\/div>\s*<\/div>/gi;
102	        const matches = html.match(resultRegex) || [];
103	
104	        for (const resultHtml of matches.slice(0, count)) {
105	            try {
106	                const titleMatch = resultHtml.match(/<a[^>]*class="[^"]*result__a[^"]*"[^>]*>([\s\S]*?)<\/a>/i);
107	                const urlMatch = resultHtml.match(/<a[^>]*href="([^"]*uddg[^"]*)"[^>]*class="[^"]*result__a/i) ||
108	                    resultHtml.match(/<a[^>]*href="([^"]*)"[^>]*class="[^"]*result__a/i);
109	                const snippetMatch = resultHtml.match(/<a[^>]*class="[^"]*result__snippet[^"]*"[^>]*>([\s\S]*?)<\/a>/i);
110	
111	                if (titleMatch && urlMatch) {
112	                    const title = this.cleanHtml(titleMatch[1]!);
113	                    let url = this.cleanUrl(urlMatch[1]!);
114	                    const snippet = snippetMatch ? this.cleanHtml(snippetMatch[1]!) : '';
115	
116	                    // Handle DuckDuckGo redirect URLs
117	                    if (url.includes('uddg=')) {
118	                        try {
119	                            const uddgMatch = url.match(/uddg=([^&]*)/);
120	                            if (uddgMatch) {
121	                                url = decodeURIComponent(uddgMatch[1]!);
122	                            }
123	                        } catch {
124	                            // Keep original if decode fails
125	                        }
126	                    }
127	
128	                    results.push({ title, url, snippet });
129	                }
130	            } catch {
131	                // Skip malformed results
132	            }
133	        }
134	
135	        return results;
136	    }
137	
138	    private cleanHtml(html: string): string {
139	        return html
140	            .replace(/<[^>]+>/g, '')
141	            .replace(/&amp;/g, '&')
142	            .replace(/&lt;/g, '<')
143	            .replace(/&gt;/g, '>')
144	            .replace(/&quot;/g, '"')
145	            .replace(/&#39;/g, "'")
146	            .replace(/&nbsp;/g, ' ')
147	            .trim();
148	    }
149	
150	    private cleanUrl(url: string): string {
151	        return url.replace(/^\/\/html\.duckduckgo\.com/, 'https://html.duckduckgo.com');
152	    }
153	
154	    private formatResults(results: SearchResult[], query: string): string {
155	        const lines = [
156	            `Ã°Å¸â€Â Web Search Results for "${query}":`,
157	            '='.repeat(50),
158	            ''
159	        ];
160	
161	        for (let i = 0; i < results.length; i++) {
162	            const r = results[i]!;
163	            lines.push(`${i + 1}. ${r.title}`);
164	            lines.push(`   URL: ${r.url}`);
165	            if (r.snippet) {
166	                lines.push(`   ${r.snippet}`);
167	            }
168	            lines.push('');
169	        }
170	
171	        return lines.join('\n');
172	    }
173	
174	    /**
175	     * Fetch and extract content from a URL
176	     */
177	    async fetchUrl(url: string): Promise<Result<EngineOutput>> {
178	        try {
179	            const response = await fetch(url, {
180	                headers: {
181	                    'User-Agent': this.userAgent,
182	                    'Accept': 'text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8',
183	                    'Accept-Language': 'en-US,en;q=0.5',
184	                    'Accept-Encoding': 'gzip, deflate, br',
185	                    'DNT': '1',
186	                    'Connection': 'keep-alive'
187	                }
188	            });
189	
190	            if (!response.ok) {
191	                return {
192	                    ok: false,
193	                    error: new Error(`Failed to fetch ${url}: ${response.status}`)
194	                };
195	            }
196	
197	            const contentType = response.headers.get('content-type') || '';
198	
199	            if (contentType.includes('application/json')) {
200	                const data = await response.json();
201	                return {
202	                    ok: true,
203	                    value: {
204	                        output: JSON.stringify(data, null, 2),
205	                        data: { url, contentType, body: data }
206	                    }
207	                };
208	            }
209	
210	            // For HTML, extract text content
211	            const html = await response.text();
212	            const text = this.extractTextFromHtml(html);
213	
214	            return {
215	                ok: true,
216	                value: {
217	                    output: text.slice(0, 8000), // Limit output
218	                    data: { url, contentType, textLength: text.length }
219	                }
220	            };
221	        } catch (error) {
222	            return {
223	                ok: false,
224	                error: error instanceof Error ? error : new Error(String(error))
225	            };
226	        }
227	    }
228	
229	    private extractTextFromHtml(html: string): string {
230	        // Remove script and style tags
231	        let text = html
232	            .replace(/<script[^>]*>[\s\S]*?<\/script>/gi, '')
233	            .replace(/<style[^>]*>[\s\S]*?<\/style>/gi, '')
234	            .replace(/<nav[^>]*>[\s\S]*?<\/nav>/gi, '')
235	            .replace(/<header[^>]*>[\s\S]*?<\/header>/gi, '')
236	            .replace(/<footer[^>]*>[\s\S]*?<\/footer>/gi, '')
237	            .replace(/<aside[^>]*>[\s\S]*?<\/aside>/gi, '');
238	
239	        // Extract content from main/article tags preferentially
240	        const mainMatch = text.match(/<main[^>]*>([\s\S]*?)<\/main>/i) ||
241	            text.match(/<article[^>]*>([\s\S]*?)<\/article>/i) ||
242	            text.match(/<div[^>]*class="[^"]*content[^"]*"[^>]*>([\s\S]*?)<\/div>/i);
243	
244	        if (mainMatch) {
245	            text = mainMatch[1]!;
246	        }
247	
248	        // Convert remaining HTML to text
249	        return this.cleanHtml(text)
250	            .replace(/\s+/g, ' ')
251	            .trim();
252	    }
253	
254	    public healthCheck(): { online: boolean; details: string } {
255	        return { 
256	            online: true, 
257	            details: 'WebSearchEngine free-tier substrate active.' 
258	        };
259	    }
260	}
