93	    private initDb(): void {
94	        const dir = DB_DIR;
95	        if (!existsSync(dir)) {
96	            mkdirSync(dir, { recursive: true });
97	        }
98	
99	        this.db = new Database(DB_PATH);
100	        this.db.exec(`
101	            CREATE TABLE IF NOT EXISTS embeddings (
