131	    async index(params: IndexParams): Promise<Result<EngineOutput>> {
132	        if (!this.db) return { ok: false, error: new Error('DB not initialized') };
133	
134	        const stat = statSync(params.path);
135	        const files: string[] = stat.isDirectory()
136	            ? this.collectFiles(params.path)
137	            : [params.path];
138	
139	        let indexed = 0;
140	        let skipped = 0;
141	        let failed = 0;
142	
143	        for (const file of files) {
144	            try {
145	                let content = readFileSync(file, 'utf8');
146	                const rawContent = content;
147	
148	                // Semantic Enrichment for Unified Mapsquares
149	                if (file.endsWith('.json') && file.includes('unified_extract')) {
150	                    try {
151	                        const data = JSON.parse(content);
152	                        const npcList = (data.pedagogy?.npcs || []).map((n: any) => n.npcName).filter(Boolean).join(', ');
153	                        const zoneList = (data.pedagogy?.zones || []).map((z: any) => z.name).filter(Boolean).join(', ');
154	                        const semanticHeader = `World Mapsquare [${data.worldX}, ${data.worldZ}] | Zones: ${zoneList} | NPCs: ${npcList}\n\n`;
155	                        content = semanticHeader + content;
156	                    } catch (e) {
157	                        logger.warn({ file, error: (e as Error).message }, 'Failed to parse unified JSON for semantic indexing');
158	                    }
159	                }
160	
161	                if (rawContent.length > MAX_FILE_SIZE) {
162	                    skipped++;
163	                    continue;
164	                }
165	
166	                const hash = createHash('md5').update(content).digest('hex');
167	                const relPath = stat.isDirectory() ? relative(params.path, file) : file;
168	                const id = `${params.projectId}::${relPath}`;
169	
170	                // Skip if already indexed with same hash (unless forced)
171	                if (!params.force) {
172	                    const existing = this.db.prepare('SELECT content_hash FROM embeddings WHERE id = ?').get(id) as { content_hash: string } | undefined;
173	                    if (existing?.content_hash === hash) {
174	                        skipped++;
175	                        continue;
176	                    }
177	                }
178	
179	                const embedResult = await this.client.embed(content.substring(0, MAX_EMBED_CONTENT_LENGTH));
180	                if (!embedResult.ok || !embedResult.value) {
181	                    logger.warn({ file, error: embedResult.error?.message || 'Empty embedding' }, 'Embed failed, skipping');
182	                    failed++;
183	                    continue;
184	                }
185	
186	                const embeddingBuffer = Buffer.from(embedResult.value.buffer);
187	                const snippet = content.substring(0, 350).replace(/\n/g, ' ');
188	                const metadata = JSON.stringify({
189	                    size: rawContent.length,
190	                    ext: extname(file),
191	                    indexed_by: 'POG2',
192	                    is_unified_world: file.includes('unified_extract')
193	                });
194	
195	                this.db.prepare(`
196	                    INSERT OR REPLACE INTO embeddings (id, path, project_id, content_hash, embedding, snippet, metadata, indexed_at)
197	                    VALUES (?, ?, ?, ?, ?, ?, ?, ?)
198	                `).run(id, relPath, params.projectId, hash, embeddingBuffer, snippet, metadata, Date.now());
199	
200	                indexed++;
201	
202	                if (indexed % 10 === 0) {
203	                    logger.info({ indexed, total: files.length }, 'Indexing progress');
204	                }
205	            } catch (err) {
206	                logger.warn({ file, err }, 'File indexing error');
207	                failed++;
208	            }
209	        }
210	
211	        return {
212	            ok: true,
213	            value: {
214	                output: `Indexed ${indexed} files | Skipped ${skipped} | Failed ${failed}`,
215	                data: { indexed, skipped, failed, projectId: params.projectId }
216	            }
217	        };
218	    }
