350	    async deleteProject(projectId: string): Promise<Result<EngineOutput>> {
351	        if (!this.db) return { ok: false, error: new Error('DB not initialized') };
352	        const res = this.db.prepare('DELETE FROM embeddings WHERE project_id = ?').run(projectId);
353	        return {
354	            ok: true,
355	            value: {
356	                output: `Deleted ${res.changes} entries for project: ${projectId}`,
357	                data: { deleted: res.changes }
358	            }
359	        };
360	    }
361	
362	    async listProjects(): Promise<Result<EngineOutput>> {
363	        if (!this.db) return { ok: false, error: new Error('DB not initialized') };
364	        const rows = this.db.prepare('SELECT project_id, COUNT(*) as count FROM embeddings GROUP BY project_id').all() as Array<{ project_id: string; count: number }>;
365	        const output = rows.map(r => `- ${r.project_id}: ${r.count} files`).join('\n');
366	        return {
367	            ok: true,
368	            value: {
369	                output: output || 'No projects indexed',
370	                data: { projects: rows }
371	            }
372	        };
373	    }
374	
375	    async similarity(params: SimilarityParams): Promise<Result<EngineOutput>> {
376	        const contentA = readFileSync(params.fileA, 'utf8');
377	        const contentB = readFileSync(params.fileB, 'utf8');
378	
379	        const [embedA, embedB] = await Promise.all([
380	            this.client.embed(contentA.substring(0, MAX_EMBED_CONTENT_LENGTH)),
381	            this.client.embed(contentB.substring(0, MAX_EMBED_CONTENT_LENGTH))
382	        ]);
383	
384	        if (!embedA.ok) return { ok: false, error: embedA.error };
385	        if (!embedB.ok) return { ok: false, error: embedB.error };
386	
387	        const score = this.cosineSimilarity(embedA.value, embedB.value);
388	
389	        // Ternary interpretation of similarity score
390	        const tier = score >= 0.85 ? 'Yang (Highly Similar)'
391	            : score >= 0.60 ? 'YinYang (Moderately Similar)'
392	                : 'Yin (Dissimilar)';
393	
394	        return {
395	            ok: true,
396	            value: {
397	                output: `Similarity: ${score.toFixed(4)} Ã¢â‚¬â€ ${tier}\n${params.fileA} Ã¢â€ â€ ${params.fileB}`,
398	                data: { score, tier, fileA: params.fileA, fileB: params.fileB }
399	            }
400	        };
401	    }
402	
403	    private collectFiles(dirPath: string): string[] {
404	        const results: string[] = [];
405	        const IGNORED = new Set(['node_modules', '.git', 'dist', 'build', 'coverage', '.POG2-cli']);
406	
407	        const walk = (dir: string): void => {
408	            const systemRoot = getSystemRoot();
409	            try {
410	                const entries = readdirSync(dir);
411	                for (const entry of entries) {
412	                    const full = join(dir, entry);
413	                    if (SovereignIgnoreManager.isIgnored(systemRoot, full)) continue;
414	
415	                    try {
416	                        const s = statSync(full);
417	                        if (s.isDirectory()) {
418	                            walk(full);
419	                        } else if (CODE_EXTENSIONS.has(extname(entry))) {
420	                            results.push(full);
421	                        }
422	                    } catch { /* skip inaccessible */ }
423	                }
424	            } catch { /* skip inaccessible dir */ }
425	        };
426	
427	        walk(dirPath);
428	        return results;
429	    }
430	
431	    private cosineSimilarity(a: Float32Array, b: Float32Array): number {
432	        const len = Math.min(a.length, b.length);
433	        let dot = 0, normA = 0, normB = 0;
434	        for (let i = 0; i < len; i++) {
435	            dot += (a[i] ?? 0) * (b[i] ?? 0);
436	            normA += (a[i] ?? 0) ** 2;
437	            normB += (b[i] ?? 0) ** 2;
438	        }
439	        const denom = Math.sqrt(normA) * Math.sqrt(normB);
440	        return denom === 0 ? 0 : dot / denom;
441	    }
442	}
