1	import { EventEmitter } from 'events';
2	import * as chokidar from 'chokidar';
3	import { readFileSync, existsSync, statSync } from 'fs';
4	import { createHash } from 'crypto';
5	import { SovereignIgnoreManager } from '../utils/SovereignIgnoreManager.js';
6	import { createLogger } from "../utils/logger.js";
7	
8	const logger = createLogger('ASTWatcher');
9	
10	export interface WatcherEvents {
11	    fileChanged: (data: { filePath: string; hasStructuralChange: boolean }) => void;
12	    watchError: (data: { error: Error }) => void;
13	}
14	
15	/**
16	 * ASTWatcher - File system monitoring with structural change detection.
17	 */
18	export class ASTWatcher extends EventEmitter {
19	    private watcher?: chokidar.FSWatcher;
20	    private readonly fileHashes: Map<string, string> = new Map();
21	
22	    constructor(private readonly projectRoot: string) {
23	        super();
24	    }
25	
26	    async setProjectRoot(newRoot: string): Promise<void> {
27	        logger.info({ newRoot }, 'Updating AST Watcher root');
28	        if (this.watcher) await this.watcher.close();
29	        this.initialize();
30	    }
31	
32	    initialize(): void {
33	        try {
34	            this.watcher = chokidar.watch(this.projectRoot, {
35	                ignored: (path: string) => {
36	                    return SovereignIgnoreManager.isIgnored(this.projectRoot, path);
37	                },
38	                persistent: true,
39	                ignoreInitial: false
40	            });
41	
42	            this.watcher
43	                .on('add', (filePath: string) => this.handleFileChange(filePath, false))
44	                .on('change', (filePath: string) => this.handleFileChange(filePath, true))
45	                .on('error', (err: unknown) => {
46	                    const error = err instanceof Error ? err : new Error(String(err));
47	                    logger.error({ error }, 'TSC watch error');
48	                });
49	
50	        } catch (error) {
51	            logger.error({ error }, 'Failed to initialize watcher');
52	        }
53	    }
54	
55	    private handleFileChange(filePath: string, isUpdate: boolean): void {
56	        try {
57	            if (!existsSync(filePath)) return;
58	            const stat = statSync(filePath);
59	            if (stat.size > 5 * 1024 * 1024) return; // Skip files > 5MB to prevent OOM
60	            
61	            const content = readFileSync(filePath, 'utf-8');
62	            const hash = createHash('md5').update(content).digest('hex');
63	            const prev = this.fileHashes.get(filePath);
64	
65	            if (hash === prev) return;
66	            this.fileHashes.set(filePath, hash);
67	
68	            if (isUpdate) {
69	                this.emit('fileChanged', { filePath, hasStructuralChange: true });
70	            }
71	        } catch { /* ignore read failures */ }
72	    }
73	
74	    async stop(): Promise<void> {
75	        if (this.watcher) await this.watcher.close();
76	        this.removeAllListeners();
77	    }
78	
79	    public healthCheck(): { online: boolean; details: string } {
80	        return {
81	            online: !!this.watcher,
82	            details: this.watcher ? `ASTWatcher active; monitoring ${this.fileHashes.size} files.` : 'ASTWatcher inactive.'
83	        };
84	    }
85	}
