223	    private async cleanupAuditOutput(maxFiles: number = 50): Promise<void> {
224	        try {
225	            const auditDir = join(process.cwd(), 'audit_output');
226	            if (!existsSync(auditDir)) return;
227	
228	            const entries = await fsPromises.readdir(auditDir);
229	            const imageFiles = entries.filter(name => /\.(png|jpg|jpeg|webp|gif)$/i.test(name));
230	
231	            if (imageFiles.length <= maxFiles) {
232	                return;
233	            }
234	
235	            const imageStats = await Promise.all(imageFiles.map(async (name) => {
236	                const fullPath = join(auditDir, name);
237	                const stat = await fsPromises.stat(fullPath);
238	                return { name, path: fullPath, mtimeMs: stat.mtimeMs };
239	            }));
240	
241	            imageStats.sort((a, b) => a.mtimeMs - b.mtimeMs);
242	            const deleteCount = imageStats.length - maxFiles;
243	
244	            for (let i = 0; i < deleteCount; i += 1) {
245	                await fsPromises.unlink(imageStats[i].path);
246	            }
247	
248	            logger.info({ deleted: deleteCount, location: 'audit_output', keep: maxFiles }, 'Chromatic engine pruned old audit artifacts');
249	        } catch (err) {
250	            logger.warn({ err }, 'Failed to prune audit_output artifacts');
251	        }
252	    }
