290	        const rgbA = this.hexToRgb(colorA);
291	        const rgbB = this.hexToRgb(colorB);
292	
293	        return Math.sqrt(
294	            Math.pow(rgbA[0] - rgbB[0], 2) +
295	            Math.pow(rgbA[1] - rgbB[1], 2) +
296	            Math.pow(rgbA[2] - rgbB[2], 2)
