1	import { createLogger } from "../utils/logger.js";
2	// ModelData type - originally from rsmv_inspector substrate (D:\sovereign\cache_pedagogy\rsmv_inspector)
3	// Defined locally to avoid broken relative import path
4	interface ModelData { meshes: any[]; bonecount?: number; miny?: number; maxy?: number; }
5	const logger = createLogger('SpatialMetricEngine');
6	
7	export interface AABB {
8	    minX: number;
9	    maxX: number;
10	    minY: number;
11	    maxY: number;
12	    minZ: number;
13	    maxZ: number;
14	}
15	
16	export interface MetricProfile {
17	    polyCount: number;
18	    vertexCount: number;
19	    aabb: AABB;
20	    dimensions: {
21	        width: number;
22	        height: number;
23	        depth: number;
24	    };
25	    volume: number;
26	    vertexDensity: number;
27	}
28	
29	/**
30	 * SpatialMetricEngine â€” High-fidelity 3D geometric forensics
31	 * Calculates metrics directly from extracted ModelData buffers
32	 */
33	export class SpatialMetricEngine {
34	
35	    /**
36	     * Calculates a comprehensive metric profile for a given 3D model
37	     */
38	    public static calculateProfile(model: ModelData): MetricProfile {
39	        let polyCount = 0;
40	        let vertexCount = 0;
41	
42	        let minX = Infinity, maxX = -Infinity;
43	        let minY = Infinity, maxY = -Infinity;
44	        let minZ = Infinity, maxZ = -Infinity;
45	
46	        for (const mesh of model.meshes) {
47	            // Polygon Count
48	            if (mesh.indices) {
49	                polyCount += mesh.indices.count / 3;
50	            }
51	
52	            // Vertex Metrics & Bounding Box
53	            const pos = mesh.attributes.pos;
54	            if (pos) {
55	                vertexCount += pos.count;
56	                for (let i = 0; i < pos.count; i++) {
57	                    const x = pos.getX(i);
58	                    const y = pos.getY(i);
59	                    const z = pos.getZ(i);
60	
61	                    if (x < minX) minX = x;
62	                    if (x > maxX) maxX = x;
63	                    if (y < minY) minY = y;
64	                    if (y > maxY) maxY = y;
65	                    if (z < minZ) minZ = z;
66	                    if (z > maxZ) maxZ = z;
67	                }
68	            }
69	        }
70	
71	        // Handle empty models
72	        if (minX === Infinity) {
73	            minX = maxX = minY = maxY = minZ = maxZ = 0;
74	        }
75	
76	        const width = maxX - minX;
77	        const height = maxY - minY;
78	        const depth = maxZ - minZ;
79	        const volume = width * height * depth;
80	        const vertexDensity = volume > 0 ? vertexCount / volume : 0;
81	
82	        return {
83	            polyCount: Math.round(polyCount),
84	            vertexCount,
85	            aabb: { minX, maxX, minY, maxY, minZ, maxZ },
86	            dimensions: { width, height, depth },
87	            volume,
88	            vertexDensity
89	        };
90	    }
91	
92	    /**
93	     * Diagnostic probe for system integrity
94	     */
95	    public healthCheck(): { online: boolean; details: string } {
96	        return {
97	            online: true,
98	            details: 'SpatialMetricEngine operational; geometric forensic substrate active.'
99	        };
100	    }
101	}
